const $searchInput=$('#SearchInput');$(function(){const filesEngine=new Bloodhound({datumTokenizer:function(document){return Bloodhound.tokenizers.whitespace(document.name)},queryTokenizer:Bloodhound.tokenizers.whitespace,remote:{url:$searchInput.data('url')+"?type=files&q=%QUERY",wildcard:'%QUERY',filter:function(response){return response.data}}});const repoEngine=new Bloodhound({datumTokenizer:function(repository){return Bloodhound.tokenizers.whitespace(repository.name)},queryTokenizer:Bloodhound.tokenizers.whitespace,remote:{url:$searchInput.data('url')+"?type=repositories&q=%QUERY",wildcard:'%QUERY',filter:function(response){return response.data}}});filesEngine.initialize();repoEngine.initialize();$searchInput.typeahead({highlight:false},{name:'files',displayKey:'value',source:filesEngine.ttAdapter(),limit:5,templates:{header:'<h6 class="suggestions-header text-primary mb-0 mx-3 mt-3 pb-2">Files</h6>',suggestion:function(document){return '<a href="'+document.links.detail+'"><div class="d-flex align-items-center"><img class="rounded-circle me-3" src="'+document.type.img+'" alt="'+document.id+'" height="32"><div class="user-info"><h6 class="mb-0">'+document.name+'</h6><small class="text-muted">'+document.size.string+"</small></div></div></a>"},notFound:'<div class="not-found px-3 py-2"><h6 class="suggestions-header text-primary mb-2">Files</h6><p class="py-2 mb-0"><i class="bx bx-error-circle bx-xs me-2"></i> No Results Found</p></div>',pending:'<div class="not-found px-3 py-2"><h6 class="suggestions-header text-primary mb-2">Files</h6><p class="py-2 mb-0"><!--<i class="fas fa-spinner fa-spin"></i>--> please wait</div>'}},{name:'repositories',displayKey:'value',source:repoEngine.ttAdapter(),limit:5,templates:{header:'<h6 class="suggestions-header text-primary mb-0 mx-3 mt-3 pb-2">Repositories</h6>',suggestion:function(repo){let content='<a href="'+repo.links.route+'" > <div class="d-flex"> <div class="flex-shrink-0"> <svg class="pc-icon wid-20 hei-20 ';content+=(repo.visibility.value==='pri')?' text-warning':' text-primary';content+='"> <use xlink:href="#custom-folder-open"></use> </svg> </div> <div class="flex-grow-1 mx-3"><h5 class="mb-1 d-grid"><span class="text-truncate w-100">'+repo.name+'</span></h5> </div></div></a>';return content},notFound:'<div class="not-found px-3 py-2"><h6 class="suggestions-header text-primary mb-2">Repository</h6><p class="py-2 mb-0"><i class="bx bx-error-circle bx-xs me-2"></i> No Results Found</p></div>',pending:'<div class="not-found px-3 py-2"><h6 class="suggestions-header text-primary mb-2">Repository</h6><p class="py-2 mb-0"><!--<i class="fas fa-spinner fa-spin"></i>--> please wait</div>'}},)});
